"""Summarize HC measurements without replacing observations or installing a mapping."""
import pathlib,json,csv,statistics,sys
R=pathlib.Path(sys.argv[1]);BASE=R.parent
rows=list(csv.DictReader((R/'curve.csv').open()));captures=[json.loads(l)['metadata'] for l in (R/'raw.jsonl').read_text().splitlines()]
def num(row,key):
 v=row.get(key)
 return float(v) if v not in (None,'') else None
def fmt(v,n=1):return 'unavailable' if v is None else f'{v:.{n}f}'
full=next(r for r in rows if r['command_pct']=='100');full_lux=num(full,'ascending_lux_window_means_mean')
compact=[]
for r in rows:
 p=int(r['command_pct']);d={'command_pct':p}
 for direction in ('ascending','descending'):
  d[direction+'_lux']=num(r,direction+'_lux_window_means_mean')
  d[direction+'_relative_output_pct']=100*d[direction+'_lux']/full_lux if d[direction+'_lux'] is not None else None
  d[direction+'_cct_planck_K']=num(r,direction+'_cct_planck_K_window_means_mean')
  d[direction+'_firmware_cct_K']=num(r,direction+'_cct_window_means_mean')
  d[direction+'_fast_modulation_pct']=num(r,direction+'_fast_observed_modulation_pct')
  d[direction+'_fast_quantization_limited']=r.get(direction+'_fast_low_signal_quantization_screen')
 compact.append(d)
with (R/'brightness-color-curve.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(compact[0]));w.writeheader();w.writerows(compact)
retest=list(csv.DictReader((R/'direction-settling-comparison.csv').open()));wave=list(csv.DictReader((R/'flicker-waveform-summary.csv').open()))
valid=[r for r in wave if r['command_pct']!='0' and r['low_signal_quantization_screen']=='False' and r['accepted']=='True']
summary={'module':'ELK11HC','complete':json.loads((R/'capture-complete.json').read_text()),'ascending_points':len(rows),'descending_points':sum(bool(r.get('descending_lux_window_means_mean')) for r in rows),'source_capture_records':len(captures),'accepted_records':sum(r['accepted'] for r in captures),'individual_samples':sum(r.get('samples',0) for r in captures),'full_output_ascent_lux':full_lux,'full_output_ascent_cct_planck_K':num(full,'ascending_cct_planck_K_window_means_mean'),'full_output_ascent_firmware_cct_K':num(full,'ascending_cct_window_means_mean'),'color_locus_unavailable_levels_ascending':[int(r['command_pct']) for r in rows if not r.get('ascending_cct_planck_K_window_means_mean')],'fast_quantization_limited_levels_ascending':[int(r['command_pct']) for r in rows if r.get('ascending_fast_low_signal_quantization_screen')=='True'],'fast_modulation_range_above_quantization_screen_pct':[min(float(r['observed_modulation_pct']) for r in valid),max(float(r['observed_modulation_pct']) for r in valid)] if valid else None,'visible_flicker_observations':json.loads((R/'visual-observations.json').read_text()),'certified_PstLM_SVM':False,'fast_flicker_excluded':False,'automation_mapping_changed':False,'absolute_color_accuracy_verified':False,'midrange_complete':json.loads((R/'midrange-complete.json').read_text()) if (R/'midrange-complete.json').exists() else None,'relative_output_reference':'Ascending measured 100% lux; no manufacturer normalization'}
(R/'summary.json').write_text(json.dumps(summary,indent=2))
lines=['# Toilet-room ELCO Koto ELK11HC measurements','', 'Measured October 7, 2026 (America/Los_Angeles). Exact module and unchanged sensor placement confirmed by user. Lutron RA3 dimmer, fixed OPT4048 sensor. No sensor calibration, scaling, or firmware changes. Existing SD mapping retained.','', '## Brightness and color curve','', '| Dimmer command | Lux (ascending) | Measured full-output fraction | Nearest-locus CCT | Firmware CCT |','|---:|---:|---:|---:|---:|']
for r in compact:
 if r['command_pct'] in (1,2,5,10,20,25,30,40,50,60,75,90,100):lines.append(f"| {r['command_pct']}% | {fmt(r['ascending_lux'],2)} | {fmt(r['ascending_relative_output_pct'])}% | {fmt(r['ascending_cct_planck_K'],0)} K | {fmt(r['ascending_firmware_cct_K'],0)} K |")
lines += ['','Commanded percent is the dimmer setting; relative output is sensor lux divided by measured ascending full-output lux. Lux is illuminance at the sensor, not fixture lumens. Ascending and descending observations remain separate in both curve CSVs. Endpoint and longer-settling checks remain separate from sweep points.','', '## Flicker and measurement limits','', 'Color mode: 25 ms conversions per channel, 30 individual samples per window, two windows per setting. Fast mode: 600 us conversions per channel and one five-second illuminance waveform per setting. Actual timestamps and sample rates are exported. Two color windows provide more than six seconds of sampling. Full-output checkpoints at 60/120 seconds; low endpoint checkpoints at 15/45 seconds. Acquisition finishes before buffered MQTT transmission.','', 'Fast min/max modulation is 100*(max-min)/(max+min). It includes sensor noise and quantization. Values at low signal are unreliable; the heuristic quantization screen flags mean signal below ten largest quantization steps, not a flicker standard. Slower captures can average out variation visible in fast mode. Timestamp-based spectral candidates and fitted 100/120 Hz components are exploratory: integration, cadence, aliasing, uneven sampling and proximity to Nyquist prevent certified frequency/amplitude conclusions. PstLM and SVM are not measured; no absence of visible or fast flicker is established.','', 'CCT uses the saved CIE 1931 2-degree observer, 5 nm Planckian integration and nearest CIE1960 uv point on a 1000–5000 K locus with 1 K steps. This is a sensor estimate, not validated absolute accuracy. Invalid low-signal x/y is retained; nearest-locus CCT remains blank. Firmware CCT is preserved independently. No invented baseline subtraction or rated-endpoint normalization.','', 'ELCO rates ELK11HC at 4000 K dimming to 2200 K: [manufacturer specifications](https://www.elcolighting.com/products/koto-led-module). This is comparison context.','', '## Shareable files','', '- `brightness-color-curve.csv`: compact 100-setting ascending/descending curve; lux, relative output, both CCT estimates and fast modulation/quantization flags.','- `curve.csv`: detailed curve, directional differences, window repeatability, and fast-waveform analyses.','- `all-captures.csv`: every attempt, including rejected and dark captures, actual timing, settings, complete begin/end metadata and derived values. Blank means unavailable.','- `individual-samples.csv`: all exposure samples with timestamps, lux, raw counts, conversion settings, and available color values.','- `raw.jsonl`: verbatim MQTT messages and stream lines, with capture metadata.','- `setting-summary.csv`: number of windows/samples, window-mean SD/CV and ranges. Window-mean SD is separate from individual-sample SD.','- `flicker-waveform-summary.csv`: min/max modulation, sampling limits, quantization screen, spectral candidates and 100/120 Hz fits.','- `capture-analysis.csv`: individual lux/color sample statistics.','- `direction-settling-comparison.csv`: signed repeated endpoint and midrange differences.','- `protocol.json`, `firmware-metadata.json`, `original-state.json`, `restored-state.json`: reproducibility and restoration records.','- `export-audit.json`: CSV/source record and value reconciliation.','', 'Visible flicker was not visually assessed; user said they had not watched for flicker. No SD visual observations were transferred.','', 'Original light, automation, calibration lock, and manual-brightness hold restoration: '+str(summary['complete']['restoration_verified'])+'. No mapping was deployed.']
(R/'README.md').write_text('\n'.join(lines)+'\n');print(json.dumps(summary,indent=2))
